<?php
/**
 * One-time WP Rocket settings seeding via a real authenticated admin request.
 *
 * WP Rocket writes its default option set only from an admin-page context
 * (inc/admin/upgrader.php: rocket_upgrader → wp_rocket_first_install), which wp-cli
 * activation does not provide (is_admin() is false under wp-cli — verified against
 * WP-CLI 2.12.0). Without this seeding, every admin-context visitor later creates
 * options mid-suite, folding time into fixture runs. This seeding does exactly what a
 * first manual visit does: an authenticated wp-admin request, cookies generated by
 * WordPress itself, so no credential value is ever printed or logged.
 *
 * Run: php /mnt/seed-settings.php   (from the wp-bootstrap compose service)
 *
 * Exit codes: 0 settings exist · 1 admin request failed · 2 settings still absent ·
 *             3 WordPress load failed
 */

if ( ! defined( 'WP_USE_THEMES' ) ) {
	define( 'WP_USE_THEMES', false );
}
require '/var/www/html/wp-load.php'; // phpcs:ignore WordPress.Security.NonceVerification

// The wp-admin hostname resolves on the compose network (service name), never via the
// published host port — no dependency on the host's port availability here.
$admin_url  = 'http://wordpress/wp-admin/index.php';
$cookiehash = md5( get_option( 'siteurl' ) );
$expiration = time() + 1200;

$auth_cookie  = wp_generate_auth_cookie( 1, $expiration, 'auth' );
$login_cookie = wp_generate_auth_cookie( 1, $expiration, 'logged_in' );

$context = stream_context_create(
	[
		'http' => [
			'header'        => "Cookie: wordpress_${cookiehash}=${auth_cookie}; wordpress_logged_in_${cookiehash}=${login_cookie}\r\n",
			'ignore_errors' => true,
			'max_redirects' => 4,
		],
		'ssl'  => [
			// Self-signed mkcert certificates are legitimate here; identity is by URL.
			'verify_peer_name' => false,
			'verify_peer'      => false,
		],
	]
);

$response = @file_get_contents( $admin_url, false, $context );
$code     = 0;
foreach ( (array) ( $http_response_header ?? [] ) as $header ) {
	if ( preg_match( '#^HTTP/#', $header ) ) {
		$parts = explode( ' ', $header );
		$code  = (int) $parts[1];
	}
}
if ( 200 !== $code || ! is_string( $response ) || strlen( $response ) < 1000 ) {
	fwrite( STDERR, "seed: admin request failed (status ${code}) — is the wordpress service up?\n" );
	exit( 1 );
}
if ( false === get_option( 'wp_rocket_settings' ) ) {
	fwrite( STDERR, "seed: wp_rocket_settings still absent after the admin hit\n" );
	exit( 2 );
}
echo "seed: wp_rocket_settings present\n";
